<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { cartApi, orderApi } from '../../services/customerApi';
import { demoCart } from '../../mock/customerDemo';

const props = defineProps({ mode: { type: String, default: 'request' } });
const route = useRoute(); const router = useRouter(); const cart = ref({ items: [], totals: {} }); const error = ref(''); const submitting = ref(false);
const saved = JSON.parse(sessionStorage.getItem('checkout-form') || '{}');
const form = ref({ receiverName: saved.receiverName || '', receiverPhone: saved.receiverPhone || '', shippingAddress: saved.shippingAddress || '', city: saved.city || '', shippingProvider: saved.shippingProvider || 'Giao hàng tiêu chuẩn', shippingMethod: saved.shippingMethod || 'DELIVERY', note: saved.note || '' });
const heading = computed(() => props.mode === 'payment' ? 'Thanh toán' : 'Gửi yêu cầu thuê');
const money = (value) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value || 0);
async function load() { if (route.query.demo === '1') { cart.value = structuredClone(demoCart); return; } try { cart.value = (await cartApi.get()).data; } catch (e) { error.value = e.response?.data?.error?.message || 'Không thể tải thông tin checkout.'; } }
function next() { sessionStorage.setItem('checkout-form', JSON.stringify(form.value)); router.push(route.query.demo === '1' ? '/customer/checkout?demo=1' : '/customer/checkout'); }
async function pay() { error.value = ''; submitting.value = true; if (route.query.demo === '1') { setTimeout(() => router.push('/customer/checkout/result?demo=1'), 450); return; } try { const response = await orderApi.checkout({ ...form.value, cartItemIds: cart.value.items.map((item) => item.id) }); sessionStorage.removeItem('checkout-form'); window.location.assign(response.data.paymentUrl); } catch (e) { error.value = e.response?.data?.error?.message || 'Không thể tạo đơn thuê.'; } finally { submitting.value = false; } }
onMounted(load);
</script>
<template><div class="container py-4"><div class="d-flex align-items-center gap-2 mb-4"><span class="rounded-circle step" :class="{ active: mode === 'request' }">1</span><span>Thông tin thuê</span><span class="text-muted">—</span><span class="rounded-circle step" :class="{ active: mode === 'payment' }">2</span><span>Thanh toán</span></div><h1 class="h3 mb-4">{{ heading }}</h1><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="row g-4"><section class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h5">Địa chỉ nhận đồ</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Người nhận</label><input v-model="form.receiverName" class="form-control"></div><div class="col-md-6"><label class="form-label">Số điện thoại</label><input v-model="form.receiverPhone" class="form-control"></div><div class="col-12"><label class="form-label">Địa chỉ</label><input v-model="form.shippingAddress" class="form-control"></div><div class="col-md-6"><label class="form-label">Tỉnh / thành phố</label><input v-model="form.city" class="form-control"></div><div class="col-md-6"><label class="form-label">Đơn vị vận chuyển</label><input v-model="form.shippingProvider" class="form-control"></div><div class="col-12"><label class="form-label">Phương thức nhận</label><select v-model="form.shippingMethod" class="form-select"><option value="DELIVERY">Giao tận nơi</option><option value="PICKUP">Tự đến lấy</option></select></div><div class="col-12"><label class="form-label">Ghi chú cho chủ đồ</label><textarea v-model="form.note" class="form-control" rows="3"></textarea></div></div></div></div><div v-if="mode === 'payment'" class="card mt-3"><div class="card-body"><h2 class="h5">Phương thức thanh toán</h2><label class="border rounded p-3 d-flex align-items-center gap-2 w-100"><input checked type="radio" name="pay"><span class="fw-semibold">VNPay sandbox</span><span class="ms-auto text-muted small">Thanh toán an toàn</span></label></div></div></section><aside class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Đơn thuê của bạn</h2><div v-for="item in cart.items" :key="item.id" class="small border-bottom py-2"><div class="fw-semibold">{{ item.product.name }}</div><div class="text-muted">{{ item.totals.rentalDays }} ngày · SL {{ item.quantity }}</div></div><div class="d-flex justify-content-between mt-3"><span>Tổng thanh toán</span><strong class="text-danger">{{ money(cart.totals.totalAmount) }}</strong></div><button v-if="mode === 'request'" class="btn btn-primary w-100 mt-3" @click="next">Tiếp tục thanh toán</button><button v-else class="btn btn-primary w-100 mt-3" :disabled="submitting || !cart.items.length" @click="pay">{{ submitting ? 'Đang tạo thanh toán...' : 'Thanh toán bằng VNPay' }}</button></div></div></aside></div></div></template>
<style scoped>.step{width:26px;height:26px;display:inline-grid;place-items:center;background:#ddd;font-size:.8rem}.step.active{background:var(--bs-primary);color:#fff}</style>
